/* ============================================================
   THUMBNAIL SVG GENERATION — original abstract motifs, no
   copyrighted or third-party imagery.
   ============================================================ */
function thumbSVG(motif, seed){
  const rand = (n)=> (Math.sin(seed*99 + n*17) + 1)/2;
  const magenta = "#E6007A", cyan = "#2FE8CE";
  let inner = '';
  if(motif === 'code'){
    for(let i=0;i<5;i++){
      const y = 20 + i*18 + rand(i)*6;
      const w = 40 + rand(i+10)*140;
      const col = i%2===0 ? magenta : cyan;
      inner += `<rect x="24" y="${y}" width="${w}" height="6" rx="3" fill="${col}" opacity="0.55"/>`;
    }
    inner += `<text x="24" y="140" font-family="monospace" font-size="12" fill="${cyan}" opacity="0.5">&lt;/&gt;</text>`;
  } else if(motif === 'chart'){
    let bars = '';
    for(let i=0;i<10;i++){
      const h = 20 + rand(i)*90;
      bars += `<rect x="${20+i*26}" y="${160-h}" width="14" height="${h}" rx="2" fill="${i%3===0?magenta:cyan}" opacity="0.6"/>`;
    }
    inner = bars;
  } else if(motif === 'candles'){
    let candles = '';
    for(let i=0;i<12;i++){
      const base = 90 + rand(i)*30;
      const h = 20 + rand(i+3)*60;
      const up = rand(i+7) > 0.5;
      const col = up ? cyan : magenta;
      candles += `<line x1="${18+i*22}" y1="${base-h-14}" x2="${18+i*22}" y2="${base+14}" stroke="${col}" stroke-width="1.5" opacity="0.5"/>`;
      candles += `<rect x="${12+i*22}" y="${base-h/2}" width="12" height="${h}" fill="${col}" opacity="0.65" rx="1"/>`;
    }
    inner = candles;
  }
  return `<svg viewBox="0 0 280 180" xmlns="http://www.w3.org/2000/svg" preserveAspectRatio="xMidYMid slice">
    <defs>
      <radialGradient id="g${seed}" cx="30%" cy="20%" r="80%">
        <stop offset="0%" stop-color="#1A1D28"/>
        <stop offset="100%" stop-color="#0A0B10"/>
      </radialGradient>
    </defs>
    <rect width="280" height="180" fill="url(#g${seed})"/>
    ${inner}
  </svg>`;
}

/* ============================================================
   RENDER — mode aware
   ============================================================ */
const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

function applySplit(el){
  if(!el) return;
  const text = el.textContent;
  el.textContent = '';
  [...text].forEach((ch,i)=>{
    const span = document.createElement('span');
    span.className = 'ch';
    span.style.setProperty('--i', i);
    span.textContent = ch === ' ' ? '\u00A0' : ch;
    el.appendChild(span);
  });
}

function observeReveal(els){
  if(reduceMotion){ els.forEach(el=>el.classList.add('in')); return; }
  const obs = new IntersectionObserver((entries)=>{ entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('in'); obs.unobserve(e.target); } }); },{threshold:0.12});
  els.forEach(el=>obs.observe(el));
}
function observeStatCounters(els){
  const obs = new IntersectionObserver((entries)=>{
    entries.forEach(e=>{
      if(e.isIntersecting){
        const el = e.target;
        const final = parseFloat(el.getAttribute('data-count'));
        const suffix = el.getAttribute('data-suffix') || '';
        if(reduceMotion){ el.textContent = final+suffix; obs.unobserve(el); return; }
        const duration = 1000, start = performance.now();
        function tick(now){
          const p = Math.min((now-start)/duration,1);
          const eased = 1-Math.pow(1-p,3);
          el.textContent = Math.round(final*eased)+suffix;
          if(p<1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
        obs.unobserve(el);
      }
    });
  },{threshold:0.5});
  els.forEach(el=>obs.observe(el));
}
function observeSkillBars(els){
  const obs = new IntersectionObserver((entries)=>{
    entries.forEach(e=>{
      if(e.isIntersecting){
        e.target.style.width = e.target.getAttribute('data-level')+'%';
        obs.unobserve(e.target);
      }
    });
  },{threshold:0.3});
  els.forEach(el=>obs.observe(el));
}

function render(mode){
  currentMode = mode;
  try{ localStorage.setItem('portfolio-mode', mode); }catch(e){}
  const C = CONTENT[mode];
  document.body.setAttribute('data-mode', mode);
  document.title = C.docTitle;

  // hero + nav + cta text
  document.getElementById('hero-eyebrow').textContent = C.heroEyebrow;
  document.getElementById('hero-name').innerHTML = C.heroNameHTML;
  document.getElementById('hero-role').textContent = C.heroRole;
  document.getElementById('hero-view-btn').textContent = C.heroViewLabel;
  const heroImg = document.getElementById('hero-photo-img');
  heroImg.src = C.heroPhoto;
  heroImg.alt = C.heroPhotoAlt;
  document.getElementById('nav-link-projects').textContent = C.navLabel;
  document.getElementById('nav-link-projects-mobile').textContent = C.navLabel;
  document.getElementById('footer-link-projects').textContent = C.navLabel;
  document.getElementById('projects-eyebrow').textContent = C.projectsEyebrow;
  document.getElementById('projects-heading').textContent = C.projectsHeading;
  applySplit(document.getElementById('projects-heading'));
  document.getElementById('projects-sub').textContent = C.projectsSub;
  document.getElementById('skills-eyebrow').textContent = C.skillsEyebrow;
  document.getElementById('skills-heading').textContent = C.skillsHeading;
  applySplit(document.getElementById('skills-heading'));
  document.getElementById('about-eyebrow').textContent = C.aboutEyebrow;
  document.getElementById('about-heading').textContent = C.aboutHeading;
  applySplit(document.getElementById('about-heading'));
  document.getElementById('about-p1').textContent = C.aboutP1;
  document.getElementById('about-p2').textContent = C.aboutP2;
  document.getElementById('cta-eyebrow').textContent = C.ctaEyebrow;
  document.getElementById('cta-heading').textContent = C.ctaHeading;
  applySplit(document.getElementById('cta-heading'));
  document.getElementById('cta-text').textContent = C.ctaText;

  // stats
  document.getElementById('stats-grid').innerHTML = C.stats.map(s=>`
    <div class="reveal"><div class="stat-num" data-count="${s.count}" data-suffix="${s.suffix}">0</div><div class="stat-label">${s.label}</div></div>
  `).join('');

  // marquee
  document.getElementById('marquee').innerHTML = [...C.marquee,...C.marquee].map(s=>`<span>${s}</span>`).join('');

  // filters
  document.getElementById('filters').innerHTML = C.categories.map((c,i)=>`<button class="filter-btn${i===0?' active':''}" data-filter="${c}">${c}</button>`).join('');

  // project / experience grid
  document.getElementById('project-grid').innerHTML = C.projects.map((p,i)=>`
    <div class="project-card reveal" data-tags="${p.tags.join('|')}" data-idx="${i}">
      <div class="pc-thumb">
        ${thumbSVG(C.motif[p.tags[0]], i+1)}
        <div class="pc-overlay">
          ${p.github ? `<a class="pc-icon-link" href="${p.github}" target="_blank" rel="noopener" title="GitHub" onclick="event.stopPropagation()">GH</a>` : ''}
          ${p.live ? `<a class="pc-icon-link" href="${p.live}" target="_blank" rel="noopener" title="Live" onclick="event.stopPropagation()">↗</a>` : ''}
        </div>
      </div>
      <div class="pc-body">
        <div class="pc-tags">${p.tags.map(t=>`<span class="pc-tag">${t}</span>`).join('')}</div>
        <div class="pc-name">${p.name} <span class="pc-expand">${mode==='finance' ? 'Details →' : 'Case study →'}</span></div>
        <div class="pc-desc">${p.desc}</div>
        <div class="pc-stack">${p.stack.map(s=>`<span>${s}</span>`).join('')}</div>
        <div class="pc-status">${p.status}</div>
      </div>
    </div>
  `).join('');

  // skills
  document.getElementById('skill-groups').innerHTML = C.skillGroups.map(g=>`
    <div class="skill-group">
      <h3>${g.title}</h3>
      ${g.items.map(i=>`
        <div class="skill-bar-row">
          <div class="skill-bar-label"><span>${i.name}</span></div>
          <div class="skill-bar-track"><div class="skill-bar-fill" data-level="${i.level}"></div></div>
        </div>
      `).join('')}
    </div>
  `).join('');

  // wire up animations for the freshly-generated elements (and any static
  // .reveal elements — e.g. About / Contact — that haven't revealed yet)
  observeReveal(document.querySelectorAll('.reveal:not(.in)'));
  observeStatCounters(document.querySelectorAll('.stat-num'));
  observeSkillBars(document.querySelectorAll('.skill-bar-fill'));

  // mode-switch pill visuals (desktop + mobile)
  [['mode-switch','mode-switch-thumb'],['mode-switch-mobile','mode-switch-thumb-mobile']].forEach(([wrapId,thumbId])=>{
    const wrap = document.getElementById(wrapId);
    if(!wrap) return;
    wrap.querySelectorAll('button').forEach(b=>b.classList.toggle('active', b.getAttribute('data-mode')===mode));
    const activeBtn = wrap.querySelector(`button[data-mode="${mode}"]`);
    const thumb = document.getElementById(thumbId);
    if(activeBtn && thumb){
      thumb.style.width = activeBtn.offsetWidth + 'px';
      thumb.style.transform = `translateX(${activeBtn.offsetLeft - 3}px)`;
    }
  });
}

